(() => {
  const quests = [
    {id:'q1',title:'Coffee & a slow start',type:'activity',category:'food',icon:'☕',art:'coffee',place:'Student Association',time:'Today · 10:30 AM',spots:2,host:'Maya R.',description:'Grabbing a coffee before lectures. Come say hi, no big plan needed.',x:39,y:36,points:15},
    {id:'q2',title:'Study sprint at the library',type:'activity',category:'study',icon:'📚',art:'book',place:'Library',time:'Today · 12:00 PM',spots:3,host:'Omar K.',description:'One focused hour, a short break, then we call it a win.',x:23,y:44,points:20},
    {id:'q3',title:'Anyone up for a film tonight?',type:'activity',category:'movies',icon:'🎬',art:'film',place:'Innovation Lounge',time:'Today · 6:30 PM',spots:2,host:'Lina S.',description:'Picking something light and bringing snacks. Open to suggestions.',x:42,y:69,points:25},
    {id:'q4',title:'Pick up my book from the library',type:'favor',category:'favor',icon:'📖',art:'book',place:'Library',time:'Today · 1:00 PM',spots:1,host:'Sam T.',description:'Could someone grab my reserved book? I’ll meet you at the entrance and return the favor another time.',x:29,y:39,points:10},
    {id:'q5',title:'Lunch at the food hall?',type:'activity',category:'food',icon:'🥗',art:'sun',place:'Food Hall',time:'Today · 1:15 PM',spots:3,host:'Noor A.',description:'Trying the new lunch counter. Join if you’re free between classes.',x:74,y:64,points:15},
    {id:'q6',title:'Walk around DIAC Park',type:'activity',category:'hiking',icon:'🌿',art:'sun',place:'DIAC Park',time:'Tomorrow · 4:00 PM',spots:4,host:'Zayd M.',description:'A relaxed walk and a chance to get away from the screens for a bit.',x:82,y:18,points:20},
    {id:'q7',title:'Mario Kart after class',type:'activity',category:'games',icon:'🎮',art:'film',place:'Innovation Lounge',time:'Today · 5:00 PM',spots:4,host:'Priya D.',description:'Casual races, snacks, and absolutely no pressure to be good.',x:58,y:47,points:15},
    {id:'q8',title:'Open mic at the student lounge',type:'activity',category:'going-out',icon:'🎤',art:'coffee',place:'Student Association',time:'Tonight · 7:30 PM',spots:5,host:'Hana F.',description:'Live music and poetry. Come perform or just hang out with us.',x:64,y:26,points:20}
  ];
  const seedFeed = [
    {name:'Maya R.',initial:'M',time:'Yesterday · 5:42 PM',title:'A coffee turned into a new friend ☕',text:'I only meant to stop for 20 minutes. We ended up swapping campus tips and making a plan for next week.',icon:'☕',likes:8,kind:'recap'},
    {name:'Omar K.',initial:'O',time:'2 days ago',title:'Study sprint: done ✅',text:'Three of us showed up, got through the reading, and took an actual lunch break. Highly recommend.',icon:'📚',likes:5,kind:'recap'},
    {name:'Lina S.',initial:'L',time:'This week',title:'A little movie night',text:'We made a plan in the quest chat, picked a film together, and found our new Thursday ritual.',icon:'🎬',likes:12,kind:'recap'}
  ];
  const leaders = [
    ['Maya R.','M',186,12],['Omar K.','O',164,10],['Noor A.','N',142,9],['Lina S.','L',128,8],['Zayd M.','Z',110,7],['Sam T.','S',98,7],['Priya D.','P',86,6],['Alex Morgan','A',85,4],['Hana F.','H',72,5],['Yusuf H.','Y',65,4],['Rami W.','R',58,3]
  ];
  let currentFilter='all', selectedId=null, sheetExpanded=false, searchQuery='', feedFilter='for-you', points=85, completed=4, accepted=false, activeChat=false, requestedId=null, forcedTheme=null;
  let addedPosts=[];
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const categoryNames={movies:'Movies','going-out':'Going out',hiking:'Hiking',food:'Food',study:'Study',games:'Games',arts:'Arts',sports:'Sports',favor:'Favor'};
  function visibleQuests(){return quests.filter(q=>(currentFilter==='all'||q.category===currentFilter)&&(!searchQuery||`${q.title} ${q.place} ${q.description} ${categoryNames[q.category]||''}`.toLowerCase().includes(searchQuery)));}
  function renderExplore(){
    const items=visibleQuests(); $('#all-count').textContent=items.length; $('#sheet-count').textContent=items.length;
    $('#quest-pins').innerHTML=items.map(q=>`<button class="quest-pin category-${q.category} ${q.type==='favor'?'favor':''} ${q.id===selectedId?'selected':''}" style="left:${q.x}%;top:${q.y}%" aria-label="${esc(q.title)}" data-select="${q.id}"><span>${q.icon}</span></button>`).join('');
    $('#quest-stack').innerHTML=items.map(q=>`<article class="quest-card ${q.id===selectedId?'selected':''}" data-select="${q.id}"><div class="quest-art ${q.art}">${q.icon}</div><div class="quest-content"><div class="quest-meta"><span class="type-label ${q.type==='favor'?'favor':''}">${esc(categoryNames[q.category]||'Activity')}</span><span>${esc(q.time.split(' · ')[1]||q.time)}</span></div><h3>${esc(q.title)}</h3><div class="quest-location">⌖ ${esc(q.place)} · ${q.spots} spot${q.spots===1?'':'s'}</div></div>${q.id===selectedId?`<div class="quest-details"><p>${esc(q.description)}</p><div class="quest-detail-actions"><span>Hosted by ${esc(q.host)} · +${q.points} pts</span><button data-action="join" data-id="${q.id}">${requestedId===q.id?'Request sent':'I’m interested'}</button></div></div>`:''}</article>`).join('')||'<div class="empty-note">No sidequests match. Try another category or search.</div>';
    $('#map-quest-count').textContent=`${items.length} sidequest${items.length===1?'':'s'} nearby`;
    $('#sheet-handle').setAttribute('aria-expanded',String(sheetExpanded));
    $('#quest-panel').classList.toggle('expanded',sheetExpanded);
    $('#sheet-handle .handle-copy').textContent=sheetExpanded?'Nearby sidequests · swipe down to map':'List · swipe up for nearby sidequests';
    $$('.map-category-chips [data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===currentFilter));
  }
  function renderFeed(){
    let posts=[...addedPosts,...seedFeed];
    if(feedFilter==='completed') posts=posts.filter(p=>p.kind==='completed'||p.kind==='recap');
    if(feedFilter==='following') posts=posts.filter(p=>p.name==='Maya R.'||p.name==='Omar K.');
    $('#feed-list').innerHTML=posts.map(p=>`<article class="feed-card"><div class="feed-card-head"><div class="avatar">${esc(p.initial)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.time)} · Birmingham Dubai</small></div></div><div class="feed-card-body"><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p></div>${p.image?`<div class="feed-art">${p.icon||'✦'}</div>`:`<div class="feed-art">${p.icon}</div>`}<div class="feed-actions"><span>♡ ${p.likes||0} found this lovely</span><button data-action="toast" data-message="Post saved to your campus feed.">Share ↗</button></div></article>`).join('')||'<p class="empty-note">Nothing here yet. Completed quests will show up as recaps.</p>';
  }
  function renderLeaderboard(){
    const show=$('#profile-privacy').getAttribute('aria-pressed')==='true';
    let rows=leaders.filter(x=>x[0]!=='Alex Morgan'||show).map(x=>x[0]==='Alex Morgan'?[x[0],x[1],points,x[3]]:x).sort((a,b)=>b[2]-a[2]).slice(0,10);
    const top=rows.slice(0,3); $('#podium').innerHTML=[top[1],top[0],top[2]].filter(Boolean).map((p,i)=>`<div class="podium-person ${i===1?'first':''}"><div class="podium-avatar">${p[1]}</div><strong>${esc(p[0].split(' ')[0])}</strong><small>${p[2]} pts</small><div class="podium-block">${i===1?'1':i===0?'2':'3'}</div></div>`).join('');
    $('#leader-rows').innerHTML=rows.map((p,i)=>`<div class="leader-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="leader-student"><span class="avatar">${p[1]}</span><strong>${esc(p[0])}${p[0]==='Alex Morgan'?' (you)':''}</strong></span><span>${p[3]}</span><span class="points">${p[2]} pts</span></div>`).join('');
  }
  function renderProfile(){ $('#profile-points').textContent=points;$('#profile-completed').textContent=completed;$('#profile-quests').innerHTML=`<div class="profile-quest"><span class="quest-art coffee">☕</span><div><strong>Welcome coffee</strong><small>Completed · +15 points</small></div></div><div class="profile-quest"><span class="quest-art book">📚</span><div><strong>Study break with Omar</strong><small>Completed · +20 points</small></div></div>${addedPosts.filter(p=>p.kind==='completed').map(p=>`<div class="profile-quest"><span class="quest-art sun">${p.icon||'✦'}</span><div><strong>${esc(p.title)}</strong><small>Completed · +${p.points||20} points</small></div></div>`).join('')}`; }
  function renderInbox(){
    const q=quests.find(x=>x.id===requestedId);
    $('#inbox-items').innerHTML=`${q?`<button class="inbox-item ${!activeChat?'active':''}" data-action="open-request"><span class="avatar">${q.host[0]}</span><span class="inbox-copy"><strong>${esc(q.title)}</strong><small>${accepted?'You’re in · group chat ready':'Join request · awaiting host'}</small></span><span class="inbox-badge">${accepted?'JOINED':'REQUEST'}</span></button>`:''}<div class="inbox-empty-note">${accepted?'Your joined sidequest chats appear here.':'Joined sidequest chats will appear here after a host adds you.'}</div>`;
    const chatCount=accepted&&q?1:0; $('#inbox-total').textContent=chatCount; $$('.inbox-count').forEach(el=>{el.textContent=chatCount;el.hidden=chatCount===0;}); $('.request-total').textContent=accepted?'0':q?'1':'0';
    if(activeChat&&accepted&&q){
      const msgs=window.demoMessages||[{text:'Hey! Thanks for joining. Meet by the main entrance?',who:'host',time:'10:06 AM'},{text:'Sounds good, I’ll be there in a few minutes.',who:'me',time:'10:08 AM'}];
      $('#chat-area').innerHTML=`<div class="chat-head"><span class="avatar">${q.host[0]}</span><div><strong>${esc(q.title)}</strong><small>${esc(q.host)} · ${esc(q.place)} · private quest chat</small></div><button class="text-button" style="margin-left:auto" data-action="complete">Complete quest</button></div><div class="chat-scroll">${msgs.map(m=>`<div class="chat-message ${m.who==='me'?'me':''}">${esc(m.text)}<small>${esc(m.time)}</small></div>`).join('')}</div><form class="chat-compose" id="chat-form"><input name="message" placeholder="Write a message…" autocomplete="off" required><button aria-label="Send message">➤</button></form>`;
    } else if(q&&!accepted){$('#chat-area').innerHTML=`<div class="chat-empty"><div class="chat-empty-icon">◌</div><h3>Request sent</h3><p>The host can accept your request before a private quest room opens. This prototype includes a demo control for previewing that step.</p><button class="accept-demo" data-action="accept">Preview host acceptance</button></div>`;}
    else $('#chat-area').innerHTML=`<div class="chat-empty"><div class="chat-empty-icon">◌</div><h3>Your next conversation<br>starts with a quest.</h3><p>When a host accepts your request, your private quest chat will show up here.</p><button class="secondary-button" data-view="explore">Explore quests →</button></div>`;
  }
  function showView(name){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.body.classList.toggle('map-home',name==='explore');$('#top-title').textContent=({explore:'Explore',feed:'Campus feed',inbox:'Chats',leaderboard:'Leaderboard',profile:'My profile'})[name]||'Explore'; if(name==='inbox')renderInbox();window.scrollTo({top:0,behavior:'smooth'});}
  function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300);}
  function openModal(html){$('#modal-content').innerHTML=html;$('#modal-backdrop').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-content input, #modal-content textarea')?.focus(),50);}
  function closeModal(){$('#modal-backdrop').hidden=true;document.body.style.overflow='';}
  function setTheme(night){document.body.classList.toggle('theme-night',night);const toggle=$('#theme-toggle');toggle.textContent=night?'☀':'☾';toggle.setAttribute('aria-label',night?'Switch to daytime map':'Switch to nighttime map');document.querySelector('meta[name="theme-color"]')?.setAttribute('content',night?'#10172b':'#ffffff');}
  function showFilters(){openModal(`<h2 id="modal-title">Filter sidequests</h2><p>Choose the kinds of plans you want to see on the map.</p><div class="filter-modal-grid"><button class="filter-chip ${currentFilter==='all'?'selected':''}" data-filter="all">All sidequests</button>${Object.entries(categoryNames).map(([key,label])=>`<button class="filter-chip ${currentFilter===key?'selected':''}" data-filter="${key}">${esc(label)}</button>`).join('')}</div><div class="modal-actions"><button class="secondary-modal" data-action="close-modal">Close</button><button class="primary-button" data-action="close-modal">Show ${visibleQuests().length} sidequests</button></div>`);}
  function createModal(){openModal(`<h2 id="modal-title">Post a sidequest</h2><p>Make a small plan, invite someone in, and see where it goes.</p><form id="quest-form"><div class="form-grid"><div class="form-field full"><label for="q-title">Sidequest title</label><input id="q-title" name="title" maxlength="60" placeholder="e.g. Coffee before class?" required></div><div class="form-field"><label for="q-category">Category</label><select id="q-category" name="category"><option value="movies">Movies</option><option value="going-out">Going out</option><option value="hiking">Hiking</option><option value="food">Food</option><option value="study">Study</option><option value="games">Games</option><option value="arts">Arts</option><option value="sports">Sports</option></select></div><div class="form-field"><label for="q-type">Quest type</label><select id="q-type" name="type"><option value="activity">Activity — do it together</option><option value="favor">Favor — lend a hand</option></select></div><div class="form-field"><label for="q-place">Meeting place</label><select id="q-place" name="place"><option>Student Association</option><option>Library</option><option>Food Hall</option><option>Innovation Lounge</option><option>DIAC Park</option><option>Other public place</option></select></div><div class="form-field"><label for="q-time">When</label><input id="q-time" name="time" type="datetime-local" required></div><div class="form-field"><label for="q-spots">People needed</label><select id="q-spots" name="spots"><option>1</option><option selected>2</option><option>3</option><option>4</option></select></div><div class="form-field full"><label for="q-description">A little more detail</label><textarea id="q-description" name="description" maxlength="240" placeholder="What should people know?"></textarea></div></div><p class="form-note">Prototype demo: posts are only saved in this browser session. Meet in public campus places.</p><div class="modal-actions"><button type="button" class="secondary-modal" data-action="close-modal">Cancel</button><button class="primary-button">Post sidequest ↗</button></div></form>`);}
  function completeModal(){const q=quests.find(x=>x.id===requestedId);openModal(`<h2 id="modal-title">Mark this quest complete</h2><p>Share a quick photo to celebrate the moment. A real version would securely store proof and let both participants confirm.</p><form id="complete-form"><div class="form-field"><label for="proof">Add a photo (optional demo preview)</label><input id="proof" type="file" accept="image/*"></div><div id="proof-preview" class="form-note">No image will be uploaded in this prototype.</div><div class="modal-actions"><button type="button" class="secondary-modal" data-action="close-modal">Not yet</button><button class="primary-button">Complete · +${q?.points||20} pts</button></div></form>`);}
  function bind(){
    document.addEventListener('click',e=>{
      const view=e.target.closest('[data-view]');if(view){e.preventDefault();showView(view.dataset.view);return;}
      const f=e.target.closest('[data-filter]');if(f){currentFilter=f.dataset.filter;selectedId=null;renderExplore();if(f.closest('#modal-content'))closeModal();return;}
      const ft=e.target.closest('[data-feed]');if(ft){feedFilter=ft.dataset.feed;$$('[data-feed]').forEach(x=>x.classList.toggle('active',x===ft));renderFeed();return;}
      const action=e.target.closest('[data-action]');if(action){
      switch(action.dataset.action){case'create':createModal();break;case'filters':showFilters();break;case'close-modal':closeModal();break;case'toggle-theme':setTheme(!document.body.classList.contains('theme-night'));break;case'recenter':toast('Map centered on Birmingham Dubai campus.');break;case'toast':toast(action.dataset.message||'Coming soon.');break;case'show-all':currentFilter='all';sheetExpanded=true;renderExplore();if(action.closest('#modal-content'))closeModal();break;case'join':requestedId=action.dataset.id;accepted=false;activeChat=false;renderExplore();showView('inbox');toast('Request sent to the quest host. A group chat opens after the host accepts.');break;case'accept':accepted=true;activeChat=true;renderInbox();toast('Demo host accepted — you’re now in the sidequest chat.');break;case'open-request':activeChat=accepted;renderInbox();break;case'complete':completeModal();break;case'edit-profile':openModal(`<h2 id="modal-title">Your profile</h2><p>Profile editing is a visual preview. Your demo profile is campus-only.</p><div class="form-field"><label>Name</label><input value="Alex Morgan"></div><div class="form-field" style="margin-top:10px"><label>About you</label><textarea>Here for good coffee, spontaneous plans, and meeting people outside my course.</textarea></div><div class="modal-actions"><button class="primary-button" data-action="close-modal">Done</button></div>`);break;}
      return;}
      const sel=e.target.closest('[data-select]');if(sel){selectedId=sel.dataset.select;renderExplore();return;}
    });
    $('#sheet-handle').addEventListener('click',()=>{sheetExpanded=!sheetExpanded;renderExplore();});
    let swipeStartY=null;$('#sheet-handle').addEventListener('pointerdown',e=>{swipeStartY=e.clientY;});$('#sheet-handle').addEventListener('pointerup',e=>{if(swipeStartY===null)return;const delta=swipeStartY-e.clientY;swipeStartY=null;if(Math.abs(delta)>28){sheetExpanded=delta>0;renderExplore();}});
    $('#quest-search').addEventListener('input',e=>{searchQuery=e.target.value.trim().toLowerCase();$('#clear-search').hidden=!searchQuery;renderExplore();});
    $('#clear-search').addEventListener('click',()=>{$('#quest-search').value='';searchQuery='';$('#clear-search').hidden=true;renderExplore();$('#quest-search').focus();});
    $('#profile-privacy').addEventListener('click',e=>{const b=e.currentTarget;b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');renderLeaderboard();toast(b.getAttribute('aria-pressed')==='true'?'You’re now visible on the leaderboard.':'You’re hidden from the leaderboard.');});
    $('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
    document.addEventListener('submit',e=>{
      if(e.target.id==='quest-form'){e.preventDefault();const d=new FormData(e.target),category=d.get('type')==='favor'?'favor':d.get('category');const icons={movies:'🎬','going-out':'🎉',hiking:'🥾',food:'🍜',study:'📚',games:'🎮',arts:'🎨',sports:'🏐',favor:'↗'};const q={id:'q'+Date.now(),title:d.get('title'),type:d.get('type'),category,icon:icons[category]||'✦',art:category==='movies'||category==='games'?'film':category==='study'?'book':category==='food'?'coffee':'sun',place:d.get('place'),time:d.get('time')?new Date(d.get('time')).toLocaleString([],{weekday:'short',hour:'numeric',minute:'2-digit'}):'Today',spots:+d.get('spots'),host:'Alex Morgan',description:d.get('description')||'A new campus sidequest — come join!',x:18+Math.random()*68,y:20+Math.random()*60,points:category==='favor'?10:15};quests.unshift(q);closeModal();selectedId=q.id;currentFilter='all';renderExplore();showView('explore');toast('Your sidequest is on the campus map.');}
      if(e.target.id==='chat-form'){e.preventDefault();const input=e.target.elements.message,msg=input.value.trim();if(!msg)return;window.demoMessages=window.demoMessages||[{text:'Hey! Thanks for joining. Meet by the main entrance?',who:'host',time:'10:06 AM'},{text:'Sounds good, I’ll be there in a few minutes.',who:'me',time:'10:08 AM'}];window.demoMessages.push({text:msg,who:'me',time:new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})});renderInbox();$('#chat-area input')?.focus();}
      if(e.target.id==='complete-form'){e.preventDefault();const q=quests.find(x=>x.id===requestedId);if(!q)return;const file=$('#proof')?.files?.[0];if(!file){toast('Choose a photo to complete this quest.');$('#proof')?.focus();return;}points+=q.points;completed++;q.completed=true;addedPosts.unshift({name:'Alex Morgan',initial:'A',time:'Just now',title:`Quest complete: ${q.title}`,text:`Showed up, shared the moment, and earned ${q.points} quest points.`,icon:q.icon,likes:0,kind:'completed',points:q.points});closeModal();renderProfile();renderLeaderboard();accepted=false;activeChat=false;requestedId=null;renderInbox();toast(`Quest completed · +${q.points} points (photo preview only)`);showView('profile');}
    });
    document.addEventListener('change',e=>{if(e.target.id==='proof'&&e.target.files?.[0])$('#proof-preview').textContent=`Selected: ${e.target.files[0].name}. The image remains local and is not uploaded.`;});
  }
  document.body.classList.add('map-home');setTheme(new Date().getHours()>=19||new Date().getHours()<6);
  renderExplore();renderFeed();renderLeaderboard();renderProfile();renderInbox();bind();
})();
